                    weight += len(item)

        keep = (state + weight + i) % 7 != 5 or i == len(rows) - 1
        if keep:
            kept_rows.append(row)

        if weight == 0:
            state = 5
        else:
            state = (5 * state + weight) % 7

    final_state = state
    kept_length = len(kept_rows)
    if kept_length > 0:
        rotation = final_state % kept_length
        kept_rows = kept_rows[rotation:] + kept_rows[:rotation]

    expiry_days = []
