        if len(row) == 2 and isinstance(row[0], int) and isinstance(row[1], int):
            day = row[0]
            lifetime = row[1]
            expiry = day + lifetime
            while expiry % 7 == 5 or expiry % 7 == 6:
                expiry += 1
            expiry_days.append(expiry)

    return expiry_days

